  /**
   * what a buyer reads before paying
   */
  description?: string;
  /**
   * the price; 0 or omitted is a free product. When items include other products, this is the price ON TOP of theirs
   */
  priceAmount?: number;
  /**
   * VRSC (default) or USD
   */
