  /**
   * the content a buyer receives: resource ids ("res_1"), named files ({resourceId, title}), folders ({folder: "Unit 1", items: […]}) or other products ({productId}) for a bundle
   */
  items?: any[];
  /**
   * how many may be sold; omit for unlimited
   */
