/**
 * TextChat.message-owner — The message that was posted into the owner's agent channel, authored by the agent.
 */
export type TextChatMessageOwnerResult = {channelId: string, messageId: string, createdAt: string};

/**
 * TextChat.message-owner — Delivers a message authored by the AI agent itself (NOT by the logged-in user) into a user's dedicated agent-to-user channel, resolved from source `userAIAgent:{userId}:{agentId}`. The recipient sees the agent as the author and the channel is created on first use. This is the INVASIVE owner-notification channel: use it to ping/notify the owner (pass the owner's userId) — or, occasionally, any other user. Unlike send-message (which sends as the logged-in user), this is authored by the agent. Silent toward the UI — does NOT open the TextChat application or change the active channel.
 */
export interface TextChatMessageOwnerParams {
  /**
   * Recipient user ID. The user who will receive the message in their agent channel.
   */
  userId: string;
  /**
   * The calling agent's own ID. Used to address the dedicated `userAIAgent:{userId}:{agentId}` channel so the message is authored by this agent.
   */
  agentId: string;
  /**
   * The message body to send.
   */
  text: string;
  /**
   * Optional interactive buttons rendered below the message body. Pass a real JSON array (NOT a JSON-stringified array). Each entry MUST be an object with this exact NESTED shape: `{text: string, intent: {applicationId: string, action: string, params?: object}}`. Do NOT flatten `applicationId`/`action` onto the button itself — `intent` is a sub-object. `text` is the visible label. Clicking dispatches `intent` via Application.run on the recipient's client (use an `applicationId` + `action` the recipient's app exposes — see other service manifests for valid pairs). Entries that are malformed are repaired-or-dropped by the service and reported back in `buttonWarnings`; check that field on the response and use the canonical shape going forward. Example: `[{"text":"Open profile","intent":{"applicationId":"valuguru","action":"open-agent","params":{"agentId":"agent_xxx"}}}]`.
   */
  buttons?: Record<string, any>[];
  /**
   * Optional message customParams. Only the key `open-thread` is accepted (any other key is dropped by the service). Pass `{"open-thread": true}` ONLY when the recipient explicitly expects your outreach (e.g. you are responding to their team-member avatar click) — it force-opens the chat thread on their screen, which is invasive.
   */
  customParams?: Record<string, any>;
}

/**
 * TextChat.send-message — The message that was posted, authored by the current user.
 */
export type TextChatSendMessageResult = {channelId: string, messageId: string, createdAt: string};

/**
 * TextChat.send-message — Sends a text message to a text-chat channel. You must provide EITHER a channelId (preferred when you already have one) OR a userId (for a direct message — the service resolves the direct channel automatically). Silent — does NOT open the TextChat application, does NOT change the active channel, does NOT affect any UI. Encryption is handled automatically if the channel is encrypted.
 */
export interface TextChatSendMessageParams {
  /**
   * The message body to send.
   */
  text: string;
  /**
   * Target channel ID. Use this when you already know the channel (e.g. from a platform event). Takes precedence over userId.
   */
  channelId?: string;
  /**
   * Target user ID for a direct message. The service resolves the direct channel by calling channel:getDirectChannel under the hood. Ignored if channelId is also provided.
   */
  userId?: string;
  /**
   * Optional interactive buttons rendered below the message body. Pass a real JSON array (NOT a JSON-stringified array). Each entry MUST be an object with this exact NESTED shape: `{text: string, intent: {applicationId: string, action: string, params?: object}}`. Do NOT flatten `applicationId`/`action` onto the button itself — `intent` is a sub-object. `text` is the visible label. Clicking dispatches `intent` via Application.run on the recipient's client (use an `applicationId` + `action` the recipient's app exposes — see other service manifests for valid pairs). Entries that are malformed are repaired-or-dropped by the service and reported back in `buttonWarnings`; check that field on the response and use the canonical shape going forward. Example: `[{"text":"Open profile","intent":{"applicationId":"valuguru","action":"open-agent","params":{"agentId":"agent_xxx"}}}]`.
   */
  buttons?: Record<string, any>[];
  /**
   * Optional message customParams. Only the key `open-thread` is accepted (any other key is dropped by the service). Pass `{"open-thread": true}` ONLY when the recipient explicitly expects your outreach (e.g. you are responding to their team-member avatar click) — it force-opens the chat thread on their screen, which is invasive.
   */
  customParams?: Record<string, any>;
}

